const e="b15d84c82f7d",n="vertaler (claude-opus-5-5)",i="2026-10-20",t=[{personId:"B",after:[],nudge:"Fang bei Bernd an. Er befand sich direkt neben einem Tisch. Such den Tisch und schau, welche Felder daneben frei sind.",reasoning:"Der Tisch steht in Reihe 4, Spalte 4. Links davon, in Reihe 4, Spalte 3, steht ein Bücherregal, und dort kann niemand stehen. Direkt neben dem Tisch bleibt also nur ein Feld übrig.",answer:"Bernd steht in Reihe 3, Spalte 4, direkt über dem Tisch. Auf dem anderen Feld neben dem Tisch steht ein Bücherregal."},{personId:"A",after:["B"],nudge:"Schau dir Anna an. Sie befand sich in Spalte 2. Welche Felder in Spalte 2 kommen noch infrage?",reasoning:"In Reihe 1, Spalte 2 steht ein Schrank und in Reihe 4, Spalte 2 ein Bücherregal: Dort kann niemand stehen. Jede Reihe enthält genau eine Person, und Reihe 3 ist schon von Bernd besetzt. In Spalte 2 bleibt also nur ein Feld übrig.",answer:"Anna steht in Reihe 2, Spalte 2. In Spalte 2 stehen ein Schrank (Reihe 1) und ein Bücherregal (Reihe 4), und Reihe 3 ist von Bernd besetzt."},{personId:"C",after:["B","A"],nudge:"Schau dir Christina an. Sie befand sich bei einem Fenster. Such die Fenster auf dem Grundriss.",reasoning:"Es gibt Fenster bei drei Feldern: Reihe 1, Spalte 3; Reihe 3, Spalte 1; und Reihe 4, Spalte 4. In Reihe 4, Spalte 4 steht ein Tisch, und Reihe 3 ist schon von Bernd besetzt. Welches Fenster bleibt übrig?",answer:"Christina steht in Reihe 1, Spalte 3, beim Fenster an der Oberseite. Das Fenster in Reihe 3 fällt wegen Bernd weg, und beim Fenster in Reihe 4 steht ein Tisch."},{personId:"V",after:["B","A","C"],nudge:"Viktoria ist das Opfer und hat keine Karte. Schau, welche Reihe und welche Spalte noch leer sind.",reasoning:"Jede Reihe und jede Spalte enthält genau eine Person. Bernd, Anna und Christina stehen schon in den Reihen 3, 2 und 1 und in den Spalten 4, 2 und 3. Nur Reihe 4 und Spalte 1 sind noch leer.",answer:"Viktoria steht in Reihe 4, Spalte 1. Das ist die einzige Reihe und die einzige Spalte, in der noch niemand steht."}],a="Viktoria befand sich im Weinkeller. Bernd ist die einzige verdächtige Person dort (Anna und Christina befanden sich im Arbeitszimmer), also ist Bernd der Täter.",r={verdict:"goed",model:"keurder (claude-opus-5-5)",date:"2026-10-20"},s={source:e,model:n,date:i,steps:t,murderer:a,review:r},d="850dbab4bf0c",h="vertaler + keurder (claude-opus-5-5)",l="2026-10-20",u=[{personId:"C",after:[],nudge:"Fang bei Christina an. Sie befand sich in der untersten Reihe. Welche Felder in Reihe 4 sind frei?",reasoning:"Die unterste Reihe ist Reihe 4. In den Spalten 2, 3 und 4 dieser Reihe stehen Tische, und dort kann niemand stehen. Es bleibt also nur ein Feld übrig.",answer:"Christina steht in Reihe 4, Spalte 1. Die anderen Felder in Reihe 4 sind von Tischen bedeckt."},{personId:"A",after:["C"],nudge:"Schau dir Axel an. Er befand sich an einem Fenster. Such die Fenster auf dem Grundriss.",reasoning:"Es gibt Fenster bei drei Feldern: Reihe 1, Spalte 1; Reihe 1, Spalte 3; und Reihe 4, Spalte 1. Jede Spalte enthält genau eine Person, und Spalte 1 ist schon von Christina besetzt. Welches Fenster bleibt übrig?",answer:"Axel steht in Reihe 1, Spalte 3, am Fenster an der Oberseite. Die anderen Fenster liegen in Spalte 1, und die ist von Christina besetzt."},{personId:"B",after:["C","A"],nudge:"Schau dir Bettina an. Sie war in der 2. Spalte. Welche Felder in Spalte 2 kommen noch infrage?",reasoning:"Reihe 1 ist von Axel besetzt und Reihe 4 von Christina. In Reihe 2, Spalte 2 steht ein Schrank, und dort kann niemand stehen. In Spalte 2 bleibt also nur ein Feld übrig.",answer:"Bettina steht in Reihe 3, Spalte 2. Reihe 1 und Reihe 4 sind besetzt, und in Reihe 2, Spalte 2 steht ein Schrank."},{personId:"V",after:["C","A","B"],nudge:"Veit ist das Opfer und hat keine Karte. Schau, welche Reihe und welche Spalte noch leer sind.",reasoning:"Jede Reihe und jede Spalte enthält genau eine Person. Christina, Axel und Bettina stehen schon in den Reihen 4, 1 und 3 und in den Spalten 1, 3 und 2. Nur Reihe 2 und Spalte 4 sind noch leer.",answer:"Veit steht in Reihe 2, Spalte 4. Das ist die einzige Reihe und die einzige Spalte, in der noch niemand steht."}],o="Veit befand sich im Arbeitszimmer. Axel ist die einzige verdächtige Person dort (Bettina und Christina befanden sich im Weinkeller), also ist Axel der Täter.",c={verdict:"goed",model:"keurder (claude-opus-5-5)",date:"2026-10-20"},p={source:d,model:h,date:l,steps:u,murderer:o,review:c},S="0e590a513929",g="vertaler + keurder (claude-opus-5-5)",R="2026-10-20",b=[{personId:"C",after:[],nudge:"Fang bei Carsten an. Seine Karte sagt, dass er sich auf einem Stuhl befand. Such den Stuhl auf dem Grundriss.",reasoning:"Carsten befand sich auf einem Stuhl. Es gibt nur einen Stuhl, und der steht im Arbeitszimmer. Dorthin gehört Carsten.",answer:"Carsten steht in Reihe 4, Spalte 1. Dort steht der einzige Stuhl, und laut seiner Karte befand er sich auf einem Stuhl."},{personId:"A",after:["C"],nudge:"Schau dir Alina an. Sie befand sich in der obersten Reihe. Welche Felder in Reihe 1 kommen noch infrage?",reasoning:"In Reihe 1, Spalte 2 steht ein Klavier und in Reihe 1, Spalte 3 eine Pflanze: Dort kann niemand stehen. Jede Spalte enthält genau eine Person, und Spalte 1 ist schon von Carsten besetzt. In Reihe 1 bleibt also nur ein Feld übrig.",answer:"Alina steht in Reihe 1, Spalte 4. In Reihe 1 stehen ein Klavier (Spalte 2) und eine Pflanze (Spalte 3), und Spalte 1 ist von Carsten besetzt."},{personId:"B",after:["C","A"],nudge:"Schau dir Britta an. Sie befand sich in der 2. Spalte. Welche Felder in Spalte 2 kommen noch infrage?",reasoning:"In Reihe 1 und Reihe 2 von Spalte 2 steht ein Klavier, und dort kann niemand stehen. Reihe 4 ist schon von Carsten besetzt. In Spalte 2 bleibt also nur ein Feld übrig.",answer:"Britta steht in Reihe 3, Spalte 2. Oben in Spalte 2 steht ein Klavier, und Reihe 4 ist von Carsten besetzt."},{personId:"V",after:["C","A","B"],nudge:"Vincent ist das Opfer und hat keine Karte. Schau, welche Reihe und welche Spalte noch leer sind.",reasoning:"Jede Reihe und jede Spalte enthält genau eine Person. Carsten, Alina und Britta stehen schon in den Reihen 4, 1 und 3 und in den Spalten 1, 4 und 2. Nur Reihe 2 und Spalte 3 sind noch leer.",answer:"Vincent steht in Reihe 2, Spalte 3. Das ist die einzige Reihe und die einzige Spalte, in der noch niemand steht."}],m="Vincent befand sich im Boudoir. Alina ist die einzige verdächtige Person dort (Britta und Carsten befanden sich im Arbeitszimmer), also ist Alina die Täterin.",f={verdict:"goed",model:"keurder (claude-opus-5-5)",date:"2026-10-20"},w={source:S,model:g,date:R,steps:b,murderer:m,review:f},k="f5f4c3de566b",z="vertaler (claude-opus-5-5)",B="2026-10-20",F=[{personId:"D",after:[],nudge:"Fang mit Dennis an. Seine Karte nennt ein Objekt. Wie viele dieser Objekte gibt es im Raster?",reasoning:"Dennis befand sich auf einem Stuhl. Schau auf den Grundriss: Es gibt nur einen Stuhl, im Arbeitszimmer. Auf welchem Feld steht dieser Stuhl?",answer:"Dennis steht in Reihe 5, Spalte 2. Dort steht der einzige Stuhl im Haus, und laut seiner Karte befand er sich auf einem Stuhl."},{personId:"C",after:["D"],nudge:"Schau dir Christian und die beiden Schränke an. Welche Felder liegen neben einem Schrank, und welche fallen durch die Karten von Anja und Boris weg?",reasoning:"Christian befand sich neben einem Schrank, im selben Raum. Neben dem Schrank im Schlafzimmer liegen Reihe 1, Spalte 4; Reihe 2, Spalte 5; und Reihe 3, Spalte 4. Neben dem Schrank im Weinkeller liegen Reihe 4, Spalte 5; und Reihe 5, Spalte 4. Spalte 5 gehört Anja (Spalte ganz rechts), Reihe 3 gehört Boris, und Reihe 5 ist durch Dennis besetzt. Welches Feld bleibt übrig?",answer:"Christian steht in Reihe 1, Spalte 4. Die anderen Felder neben einem Schrank fallen weg: Spalte 5 gehört Anja, Reihe 3 Boris, und Reihe 5 ist durch Dennis besetzt."},{personId:"B",after:["D","C"],nudge:"Boris war in der 3. Reihe. Geh die Felder dieser Reihe durch: Welche sind blockiert oder fallen wegen ihrer Spalte weg?",reasoning:"Boris war in der 3. Reihe. In Reihe 3, Spalte 3 steht das Klavier, dort kann niemand stehen. Spalte 2 ist durch Dennis besetzt und Spalte 4 durch Christian. Spalte 5 gehört Anja, denn sie befand sich in der Spalte ganz rechts. Welches Feld in Reihe 3 bleibt übrig?",answer:"Boris steht in Reihe 3, Spalte 1. In Spalte 3 steht das Klavier, die Spalten 2 und 4 sind durch Dennis und Christian besetzt, und Spalte 5 gehört Anja."},{personId:"V",after:["D","C","B"],nudge:"Jetzt das Opfer, Vincent. Welche Reihen und Spalten sind noch frei, und welche Spalte gehört schon Anja?",reasoning:"Die Reihen 1, 3 und 5 sind besetzt, ebenso die Spalten 1, 2 und 4. Übrig bleiben die Reihen 2 und 4 und die Spalten 3 und 5. Spalte 5 gehört Anja, also muss Vincent in Spalte 3 liegen. In Reihe 2, Spalte 3 steht das Klavier. Wo kann Vincent dann noch liegen?",answer:"Vincent liegt in Reihe 4, Spalte 3. Spalte 5 gehört Anja, also muss er in Spalte 3 liegen, und in Reihe 2, Spalte 3 steht das Klavier."},{personId:"A",after:["D","C","B","V"],nudge:"Anja ist die Letzte, die noch keinen Platz hat. Was sagt ihre Karte, und welche Reihe ist noch frei?",reasoning:"Anja befand sich in der Spalte ganz rechts, also in Spalte 5. Die Reihen 1, 3, 4 und 5 sind schon besetzt. Welches Feld in Spalte 5 bleibt dann übrig?",answer:"Anja steht in Reihe 2, Spalte 5. Laut ihrer Karte befand sie sich in der Spalte ganz rechts, und die Reihen 1, 3, 4 und 5 sind schon besetzt."}],A="Vincent liegt im Arbeitszimmer, und Dennis ist der einzige Verdächtige, der sich auch im Arbeitszimmer befand. Dennis ist also der Täter.",D={verdict:"goed",model:"keurder (claude-opus-5-5)",date:"2026-10-20"},C={source:k,model:z,date:B,steps:F,murderer:A,review:D},v="144a6a6f16d9",E="vertaler + keurder (claude-opus-5-5)",W="2026-10-20",I=[{personId:"B",after:[],nudge:"Fang mit Björn in der obersten Reihe an. Welche Felder sind dort blockiert, und was sagt Axels Karte über den Weinkeller?",reasoning:"Björn war in der obersten Reihe, also in Reihe 1. In Reihe 1, Spalte 1 steht ein Schrank, dort kann niemand stehen. Die Spalten 3, 4 und 5 von Reihe 1 gehören zum Weinkeller, und Axel war die einzige Person im Weinkeller. Björn kann also nicht dort sein. Welches Feld in Reihe 1 bleibt übrig?",answer:"Björn steht in Reihe 1, Spalte 2. In Spalte 1 steht ein Schrank, und die Spalten 3 bis 5 gehören zum Weinkeller, wo nur Axel war."},{personId:"D",after:["B"],nudge:"Schau dir Doris und die Stühle an. Welche Felder liegen direkt neben einem Stuhl im selben Raum, außerhalb des Weinkellers?",reasoning:"Doris befand sich direkt neben einem Stuhl, im selben Raum. Zwei Stühle stehen im Weinkeller, aber dort war nur Axel. Die anderen beiden stehen im Wintergarten, in Reihe 4, Spalte 2 und in Reihe 5, Spalte 1. Direkt daneben liegen Spalte 2, Reihen 3 und 5, sowie Reihe 4, Spalte 1. Spalte 2 ist durch Björn besetzt. Welches Feld bleibt übrig?",answer:"Doris steht in Reihe 4, Spalte 1, direkt neben den Stühlen im Wintergarten. Der Weinkeller gehört Axel, und die Felder in Spalte 2, Reihen 3 und 5, fallen weg, weil Björn in Spalte 2 steht."},{personId:"C",after:["B","D"],nudge:"Christina befand sich auf einem Bett. Wie viele Felder hat das Bett, und welche Reihe ist schon besetzt?",reasoning:"Es gibt ein einziges Bett, in der Bibliothek; es belegt in Spalte 5 die Reihen 3 und 4. Reihe 4 ist durch Doris besetzt. Auf welchem Feld des Betts kann Christina dann noch sein?",answer:"Christina steht in Reihe 3, Spalte 5. Das Bett belegt in Spalte 5 die Reihen 3 und 4, und Reihe 4 ist durch Doris besetzt."},{personId:"V",after:["B","D","C"],nudge:"Jetzt das Opfer, Veronika. Welche Reihen sind noch frei, und in welche davon muss Axel?",reasoning:"Die Reihen 1, 3 und 4 sind besetzt, also bleiben Reihe 2 und 5 übrig. Axel war im Weinkeller, der nur die Reihen 1 und 2 umfasst; Reihe 1 gehört Björn, also kommt Axel in Reihe 2. Veronika muss dann in Reihe 5 liegen. Die Spalten 1, 2 und 5 sind besetzt, und in Reihe 5, Spalte 3 steht der Tisch. Wo kann Veronika dann noch liegen?",answer:"Veronika liegt in Reihe 5, Spalte 4. Reihe 2 gehört Axel (Weinkeller), die Spalten 1, 2 und 5 sind besetzt, und in Reihe 5, Spalte 3 steht der Tisch."},{personId:"A",after:["B","D","C","V"],nudge:"Axel ist der Letzte, der noch keinen Platz hat. Was sagt seine Karte, und welche Reihe und Spalte sind noch frei?",reasoning:"Axel war im Weinkeller, also in Reihe 1 oder 2. Reihe 1 ist durch Björn besetzt. Spalte 4 ist durch Veronika besetzt und Spalte 5 durch Christina. Welches Feld im Weinkeller bleibt übrig?",answer:"Axel steht in Reihe 2, Spalte 3, im Weinkeller. Reihe 1 ist durch Björn besetzt, Spalte 4 durch Veronika und Spalte 5 durch Christina."}],V="Veronika liegt in der Bibliothek, und Christina ist die einzige Verdächtige, die sich auch in der Bibliothek befand. Christina ist also die Täterin.",j={verdict:"goed",model:"keurder (claude-opus-5-5)",date:"2026-10-20"},$={source:v,model:E,date:W,steps:I,murderer:V,review:j},K="dfa59a49f03b",G="vertaler + keurder (claude-opus-5-5)",_="2026-10-20",T=[{personId:"A",after:[],nudge:"Fang mit Alina an. Such das Bücherregal auf dem Grundriss und schau, welche Felder daneben frei sind.",reasoning:"Alina befand sich neben einem Bücherregal. Es gibt nur ein Bücherregal: in Reihe 5, Spalte 3, im Salon. In Reihe 4, Spalte 3 steht eine Pflanze, und Reihe 5, Spalte 2 liegt hinter einer Wand in der Halle (dort steht auch eine Pflanze). Welches Feld neben dem Bücherregal bleibt übrig?",answer:"Alina steht in Reihe 5, Spalte 4, neben dem Bücherregal. In Reihe 4, Spalte 3 steht eine Pflanze, und Reihe 5, Spalte 2 liegt hinter einer Wand in der Halle."},{personId:"C",after:["A"],nudge:"Jetzt Christian in der 4. Reihe. Leg seine Karte neben die von Bernd, und schau auch auf Alina.",reasoning:"Christian war in der 4. Reihe. Die Spalten 1 und 2 von Reihe 4 gehören zur Halle, und Bernd war allein in der Halle, also kann Christian dort nicht sein. In Reihe 4, Spalte 3 steht eine Pflanze, und Spalte 4 ist durch Alina besetzt. Welches Feld in Reihe 4 bleibt übrig?",answer:"Christian steht in Reihe 4, Spalte 5. Die Spalten 1 und 2 von Reihe 4 liegen in der Halle, wo Bernd allein war, in Spalte 3 steht eine Pflanze, und Spalte 4 ist durch Alina besetzt."},{personId:"D",after:["A","C"],nudge:"Schau dir Doris und Spalte 2 an. Welche Felder fallen durch Bernds Karte weg?",reasoning:"Doris war in der 2. Spalte. Die Reihen 3, 4 und 5 von Spalte 2 gehören zur Halle, wo Bernd allein war; dort kann Doris nicht sein. In Reihe 1, Spalte 2 steht ein Schrank, dort kann niemand stehen. Welches Feld in Spalte 2 bleibt dann übrig?",answer:"Doris steht in Reihe 2, Spalte 2. Die Reihen 3 bis 5 von Spalte 2 liegen in der Halle, wo Bernd allein war, und in Reihe 1, Spalte 2 steht ein Schrank."},{personId:"B",after:["A","C","D"],nudge:"Bernd war allein in der Halle. Welche Reihen und Spalten der Halle sind noch frei?",reasoning:"Die Halle umfasst die Reihen 3, 4 und 5 in den Spalten 1 und 2. Reihe 4 ist durch Christian besetzt, Reihe 5 durch Alina und Spalte 2 durch Doris. Welches Feld der Halle bleibt dann für Bernd übrig?",answer:"Bernd steht in Reihe 3, Spalte 1. In der Halle sind Reihe 4 (Christian), Reihe 5 (Alina) und Spalte 2 (Doris) schon besetzt."},{personId:"V",after:["A","C","D","B"],nudge:"Valentin ist der Letzte, der noch keinen Platz hat. Welche Reihe und welche Spalte sind noch frei?",reasoning:"Alle Verdächtigen stehen schon. Reihe 1 ist die einzige freie Reihe und Spalte 3 die einzige freie Spalte. Wo kreuzen sich die beiden?",answer:"Valentin liegt in Reihe 1, Spalte 3. Reihe 1 und Spalte 3 sind die einzige Reihe und Spalte, in denen noch niemand steht."}],P="Valentin liegt im Flur. Doris ist die einzige Verdächtige im Flur, also ist Doris die Täterin.",H={verdict:"goed",model:"keurder (claude-opus-5-5)",date:"2026-10-20"},M={source:K,model:G,date:_,steps:T,murderer:P,review:H},L="74a91d976380",x="vertaler + keurder (claude-opus-5-5)",J="2026-10-20",N=[{personId:"C",after:[],nudge:"Fang bei Christina an. Kombiniere ihre Karte mit der von Daniel: Welche Frau kann mit ihm im selben Raum stehen? Schau dir danach die Räume in der oberen Hälfte an.",reasoning:"Christina ist die einzige Frau, also steht Christina laut Daniels Karte im selben Raum wie Daniel. Christina steht in der oberen Hälfte, aber nicht in Reihe 1: Diese Reihe gehört Andreas (seine Karte: oberste Reihe). Im Weinkeller bleibt dann nur Reihe 2 übrig, im Salon ebenfalls, denn dort steht in Reihe 3 ein Tisch. Christina und Daniel können aber nicht beide in derselben Reihe stehen. Im Schlafzimmer müssten Bernd, Christina und Daniel zusammen in Reihe 2 und 3 stehen, und das sind nur zwei Reihen. Welcher Raum bleibt dann übrig, und welches freie Feld hat er in der oberen Hälfte?",answer:"Christina steht in Reihe 3, Spalte 2. Nur im Boudoir passen Christina und Daniel zusammen, und das einzige freie Feld des Boudoirs in der oberen Hälfte ist dieser Teppich."},{personId:"A",after:["C"],nudge:"Schau dir Andreas an. Seine Karte lässt in der obersten Reihe nur noch zwei Felder offen. Welche Spalte braucht Daniel im Boudoir?",reasoning:"Andreas steht in Reihe 1 und in der linken Hälfte. Das Feld in Spalte 2 ist ein Tisch, also kommen nur noch Spalte 1 und Spalte 3 infrage. Daniel steht bei Christina im Boudoir, und das Boudoir hat nur Spalte 1 und 2. Spalte 2 gehört schon Christina, also braucht Daniel Spalte 1. Welches Feld bleibt dann für Andreas übrig?",answer:"Andreas steht in Reihe 1, Spalte 3. Spalte 1 wird für Daniel im Boudoir gebraucht, und in Reihe 1 ist Spalte 2 ein Tisch."},{personId:"E",after:["C","A"],nudge:'Schau dir Erik und Bernd an. Das Schlafzimmer hat nur zwei Spalten. Was bedeutet "irgendwo rechts von Bernd" dann für Erik, und in welcher Reihe muss Bernd stehen?',reasoning:"Bernd steht im Schlafzimmer, in Spalte 5 oder 6. Erik befand sich irgendwo rechts von ihm, also steht Bernd in Spalte 5 und Erik in Spalte 6. Reihe 1 gehört Andreas und Reihe 3 Christina, also bleibt für Bernd nur Reihe 2. In Spalte 6 fallen für Erik dann Reihe 1, 2 und 3 weg, und in Reihe 4 und 5 steht ein Tisch. Wo kann Erik noch stehen?",answer:"Erik steht in Reihe 6, Spalte 6. Er muss in Spalte 6 stehen; Reihe 1 ist für Andreas, Reihe 2 für Bernd, Reihe 3 für Christina, und in Reihe 4 und 5 steht ein Tisch."},{personId:"B",after:["C","A","E"],nudge:"Bernd steht im Schlafzimmer. Streich dort die Reihen und Spalten, die schon besetzt sind.",reasoning:"Das Schlafzimmer umfasst Reihe 1 bis 3 in Spalte 5 und 6. Reihe 1 gehört Andreas, Reihe 3 Christina und Spalte 6 Erik. Welches Feld bleibt im Schlafzimmer übrig?",answer:"Bernd steht in Reihe 2, Spalte 5. Im Schlafzimmer sind Reihe 1, Reihe 3 und Spalte 6 schon besetzt."},{personId:"V",after:["C","A","E","B"],nudge:"Jetzt Vincent. Schau, welche Reihen und Spalten noch frei sind und welche Spalte Daniel schon braucht.",reasoning:"Frei sind noch Reihe 4 und 5 sowie Spalte 1 und 4. Daniel steht bei Christina im Boudoir, in Spalte 1 (Spalte 2 gehört Christina). Vincent muss also in Spalte 4. Dort steht in Reihe 5 das Bücherregal. Welches Feld bleibt übrig?",answer:"Vincent liegt in Reihe 4, Spalte 4. Spalte 1 ist für Daniel, und in Spalte 4 ist Reihe 5 ein Bücherregal."},{personId:"D",after:["C","A","E","B","V"],nudge:"Daniel ist der Letzte. Welche Reihe und welche Spalte sind noch ganz frei?",reasoning:"Es gibt nur noch eine freie Reihe und eine freie Spalte. Wo kreuzen sie sich? Schau, ob dieses Feld zu Daniels Karte passt: Er muss mit Christina im selben Raum stehen.",answer:"Daniel steht in Reihe 5, Spalte 1. Das ist die einzige freie Reihe und Spalte, und das Feld liegt im Boudoir, bei Christina."}],O="Vincent liegt in der Küche, und Erik ist der einzige Verdächtige, der dort steht. Also ist Erik der Täter.",q={verdict:"goed",model:"keurder (claude-opus-5-5)",date:"2026-10-20"},Z={source:L,model:x,date:J,steps:N,murderer:O,review:q},y="a6ef3e81331a",Q="vertaler + keurder (claude-opus-5-5)",U="2026-10-20",X=[{personId:"E",after:[],nudge:"Fang bei Erik an: Er befand sich an einem Fenster. Welche Fenster fallen durch die Karten von Alina und Christoph weg? Schau dir danach Björn an.",reasoning:"Reihe 1 ist für Alina und Spalte 6 für Christoph, also bleiben von allen Fenstern nur die bei Reihe 6, Spalten 1 und 3 übrig: Erik war in Reihe 6, in der Halle. Björn war in einer Ecke des Raums, zusammen mit einem anderen Mann: Christoph oder Erik. Die Ecken des Boudoirs, wo Christoph war, liegen alle in Reihe 1, Reihe 6 oder Spalte 6, und die sind für Alina, Erik und Christoph. Björn war also bei Erik in der Halle, in einer Ecke außerhalb von Reihe 6 und außerhalb von Spalte 4 (die ist für Diana): Reihe 5, Spalte 1. Welches Fenster bleibt für Erik übrig, jetzt, wo Spalte 1 für Björn ist?",answer:"Erik steht in Reihe 6, Spalte 3. Reihe 1 ist für Alina, Spalte 6 für Christoph und Spalte 1 für Björn, also bleibt nur das Fenster bei Reihe 6, Spalte 3 übrig."},{personId:"B",after:["E"],nudge:"Björn befand sich in einer Ecke des Raums, und in seinem Raum war außerdem ein Mann. Welcher Mann kann das sein: Christoph oder Erik?",reasoning:"Der andere Mann ist Christoph oder Erik. Christoph war in Spalte 6, im Boudoir; die Ecken des Boudoirs liegen in Reihe 1 (für Alina), Reihe 6 (von Erik besetzt) oder Spalte 6 (für Christoph). Björn war also bei Erik in der Halle. Die Halle hat ihre Ecken in Reihe 5 und Reihe 6, jeweils in Spalte 1 und Spalte 4. Reihe 6 ist besetzt und Spalte 4 ist für Diana: Welche Ecke bleibt übrig?",answer:"Björn steht in Reihe 5, Spalte 1. Er musste bei Erik in der Halle sein, und von den Ecken dort fallen Reihe 6 (Erik) und Spalte 4 (Diana) weg."},{personId:"C",after:["E","B"],nudge:"Christoph war in Spalte 6 und irgendwo oberhalb von Diana. Finde zuerst heraus, wie weit oben Diana in Spalte 4 stehen kann.",reasoning:"Diana war in Spalte 4. Reihe 1 ist für Alina, Reihe 5 und Reihe 6 sind besetzt, also hat sie noch Reihe 2, 3 oder 4. In Reihe 4, Spalte 4 stünde sie neben dem Bücherregal in Reihe 4, Spalte 3, und das geht nicht. Diana ist also in Reihe 2 oder 3. Christoph hat in Spalte 6 noch Reihe 2, 3 oder 4 frei, muss aber irgendwo oberhalb von Diana sein. Welche Reihe passt dann noch?",answer:"Christoph steht in Reihe 2, Spalte 6. Diana kann nicht tiefer als Reihe 3 stehen (Reihe 4 liegt neben dem Bücherregal), Reihe 1 ist für Alina, und Reihe 5 und 6 sind besetzt."},{personId:"D",after:["E","B","C"],nudge:"Diana war in Spalte 4. Welche Reihen sind noch frei, und wo steht das Bücherregal?",reasoning:"In Spalte 4 ist Reihe 1 für Alina, und Reihe 2, 5 und 6 sind von Christoph, Björn und Erik besetzt. In Spalte 4 bleiben also Reihe 3 und Reihe 4 übrig. Diana befand sich neben keinem Bücherregal, und in Reihe 4, Spalte 3 steht eines. Welches Feld bleibt übrig?",answer:"Diana steht in Reihe 3, Spalte 4. Reihe 1 ist für Alina, Reihe 2, 5 und 6 sind besetzt, und Reihe 4, Spalte 4 liegt neben dem Bücherregal in Reihe 4, Spalte 3."},{personId:"V",after:["E","B","C","D"],nudge:"Noch frei sind Reihe 1 und Reihe 4 sowie Spalte 2 und Spalte 5. Welche Reihe gehört Alina?",reasoning:"Reihe 1 ist für Alina, also muss Vera in Reihe 4. Dort sind Spalte 2 und Spalte 5 noch frei. In Reihe 4, Spalte 2 steht ein Bücherregal, und dort kann niemand stehen. Welches Feld bleibt übrig?",answer:"Vera liegt in Reihe 4, Spalte 5. Reihe 1 ist für Alina, und in Reihe 4, Spalte 2 steht ein Bücherregal."},{personId:"A",after:["E","B","C","D","V"],nudge:"Nur noch eine Person fehlt. Was sagt Alinas Karte?",reasoning:"Alina war in der obersten Reihe, also in Reihe 1. Alle Spalten außer Spalte 2 sind schon besetzt. Welches Feld ist es?",answer:"Alina steht in Reihe 1, Spalte 2. Sie war in der obersten Reihe, und Spalte 2 ist die einzige freie Spalte."}],Y="Christoph ist der Täter: Er ist der einzige Verdächtige im Boudoir, wo Vera gefunden wurde.",ee={verdict:"goed",model:"keurder (claude-opus-5-5)",date:"2026-10-20"},ne={source:y,model:Q,date:U,steps:X,murderer:Y,review:ee},ie="eee2a5a776d9",te="vertaler + keurder (claude-opus-5-5)",ae="2026-10-20",re=[{personId:"B",after:[],nudge:"Fang bei Bernd an: Spalte ganz rechts und eine Ecke des Raums. Schau dir danach Emil an, der sich in einer Reihe weiter unten als Bernd befand.",reasoning:"Die Spalte ganz rechts gehört komplett zum Wintergarten. Die Ecken des Wintergartens in Spalte 6 liegen in Reihe 1 und Reihe 6. Emil befand sich in einer Reihe weiter unten als Bernd. Wäre Bernd in Reihe 6, der untersten Reihe, könnte niemand weiter unten sein als er. Welche Ecke bleibt dann übrig?",answer:"Bernd steht in Reihe 1, Spalte 6. In Spalte 6 hat der Wintergarten Ecken in Reihe 1 und Reihe 6, und in Reihe 6 könnte Emil nicht in einer Reihe weiter unten als Bernd sein."},{personId:"C",after:["B"],nudge:"Carsten befand sich in der 4. Spalte. Schau dir Reihe 6 an: Wer kann dort noch sein? Denk an Emil und sein Bett.",reasoning:"Emil befand sich auf einem Bett. Die Betten liegen in Spalte 3 und Spalte 4, aber Spalte 4 ist für Carsten, also ist Emil in Spalte 3, in Reihe 3 oder 4. In Reihe 6 stehen Tische in Spalte 1 und 2 und eine Pflanze in Spalte 5, und Spalte 6 ist besetzt. Spalte 3 ist für Emil, der nicht in Reihe 6 sein kann. Wer kann Reihe 6 dann noch belegen?",answer:"Carsten steht in Reihe 6, Spalte 4. In Reihe 6 bleiben nur Spalte 3 und 4 übrig; Spalte 3 ist für Emil auf dem Bett in Reihe 3 oder 4, also ist Reihe 6 für Carsten."},{personId:"E",after:["B","C"],nudge:"Emil war auf dem Bett in Spalte 3, in Reihe 3 oder 4. Schau dir Antons Karte an: In welcher Ecke kann er sein?",reasoning:"Anton befand sich in einer Ecke des Raums, und in seinem Raum war außerdem jemand mit Brille. Spalte 3, 4 und 6 sowie Reihe 1 und 6 fallen für ihn weg. Dann bleiben die Ecken in Reihe 2, Spalte 1 (Bibliothek) sowie in Reihe 3, Spalten 1 und 2 (Gästezimmer). In der Bibliothek kann sonst niemand mehr bei ihm sein, denn Reihe 1 ist besetzt, und in Reihe 2, Spalte 2 steht ein Bücherregal. Anton ist also in Reihe 3. Welche Reihe bekommt Emil dann?",answer:"Emil steht in Reihe 4, Spalte 3. Er muss auf dem Bett in Spalte 3 sein; Reihe 3 ist für Anton, der nur in einer Ecke des Gästezimmers in Reihe 3 jemanden mit Brille bei sich haben kann."},{personId:"V",after:["B","C","E"],nudge:"Anton war in Reihe 3 des Gästezimmers, zusammen mit noch jemandem mit Brille. Wer ist das, und welche Reihe und Spalte bleiben für Valerie?",reasoning:"Anton war im Gästezimmer, in Reihe 3, wie sich vorhin gezeigt hat. Emil hat auch eine Brille, ist aber im Arbeitszimmer. Also war Daniela bei Anton im Gästezimmer. Frei sind noch Reihe 2 und Reihe 5; das Gästezimmer umfasst Reihe 3 bis 6, also bekommt Daniela Reihe 5. Anton und Daniela nehmen Spalte 1 und 2. Welche Reihe und Spalte bleiben für Valerie?",answer:"Valerie liegt in Reihe 2, Spalte 5. Daniela muss bei Anton im Gästezimmer in Reihe 5 sein, und die beiden nehmen Spalte 1 und 2; für Valerie bleiben Reihe 2 und Spalte 5."},{personId:"D",after:["B","C","E","V"],nudge:"Daniela war im Gästezimmer, in Reihe 5. Was sagt ihre Karte über Anton?",reasoning:"Daniela war bei Anton im Gästezimmer, in Reihe 5, wie sich vorhin gezeigt hat. Sie und Anton haben Spalte 1 und 2. Daniela befand sich irgendwo links von Anton. Welche der beiden Spalten liegt links?",answer:"Daniela steht in Reihe 5, Spalte 1. Sie und Anton nehmen Spalte 1 und 2, und Daniela befand sich irgendwo links von Anton."},{personId:"A",after:["B","C","E","V","D"],nudge:"Anton ist der Letzte. Welche Reihe und welche Spalte sind noch frei?",reasoning:"Alle Reihen außer Reihe 3 sind besetzt, und alle Spalten außer Spalte 2. Das Feld, in dem sie sich kreuzen, ist eine Ecke des Gästezimmers, und Daniela mit ihrer Brille ist im selben Raum, so wie seine Karte es verlangt.",answer:"Anton steht in Reihe 3, Spalte 2. Das ist das einzige freie Feld, eine Ecke des Gästezimmers, und Daniela ist mit ihm dort."}],se="Valerie liegt im Wintergarten, und Bernd ist dort der einzige Verdächtige. Bernd ist also der Täter.",de={verdict:"goed",model:"keurder (claude-opus-5-5)",date:"2026-10-20"},he={source:ie,model:te,date:ae,steps:re,murderer:se,review:de},le="fa9cb05db2c4",ue="vertaler (claude-opus-5-5)",oe="2026-10-20",ce=[{personId:"F",after:[],nudge:"Fang bei Finn und Dirk an: Dirk befand sich genau zwei Reihen unter Finn. Welche Reihen kommen für Dirk infrage, wenn du auch Anjas Karte dazunimmst?",reasoning:"In Reihe 1, Spalte 5 steht ein Bücherregal, also ist Finn nicht in Reihe 1 und Dirk (genau zwei Reihen tiefer) mindestens in Reihe 4. Anja befand sich irgendwo unterhalb von Dirk und irgendwo oberhalb von einem Mann; also ist Anja nicht in Reihe 7 und Dirk nicht in Reihe 6 oder 7. In der linken Hälfte (Spalte 1 bis 3) stehen in Reihe 4 nur Bücherregale, also ist Dirk in Reihe 5. Finn war genau zwei Reihen höher: Welches Feld in Spalte 5 ist das?",answer:"Finn steht in Reihe 3, Spalte 5. Dirk muss in Reihe 5 sein: Reihe 4 hat links nur Bücherregale, und in Reihe 6 oder 7 könnte Anja nicht irgendwo unterhalb von ihm und zugleich irgendwo oberhalb von einem Mann sein."},{personId:"C",after:["F"],nudge:"Carsten war in der 3. Spalte. Schau, welche Reihen schon für andere vergeben sind: Denk an Dirk, Anja und Emil.",reasoning:"Dirk ist in Reihe 5, wie sich vorhin gezeigt hat. Anja befand sich irgendwo unterhalb von Dirk und irgendwo oberhalb von einem Mann, also ist Anja in Reihe 6. Emil befand sich im Weinkeller (Reihe 6 und 7), also ist Emil in Reihe 7. In Spalte 3 stehen in Reihe 2, 4 und 6 ein Tisch, ein Bücherregal und ein Schrank, und Reihe 3 ist durch Finn belegt. Welches Feld bleibt für Carsten übrig?",answer:"Carsten steht in Reihe 1, Spalte 3. Reihe 3 gehört Finn, Reihe 5 Dirk, Reihe 6 Anja und Reihe 7 Emil; in Reihe 2, 4 und 6 stehen Tisch, Bücherregal und Schrank."},{personId:"A",after:["F","C"],nudge:"Anja ist in Reihe 6. Schau dir Britta an: Sie war genau eine Spalte links von Anja. Welche Spalten sind schon vergeben?",reasoning:"Anja ist in Reihe 6, wie sich vorhin gezeigt hat. Dirk befand sich in der linken Hälfte, und Spalte 3 ist durch Carsten belegt; weil Emil sich in einer Spalte weiter links als Dirk befand, ist Spalte 2 für Dirk und Spalte 1 für Emil. In Reihe 6 stehen in Spalte 3 und 5 Schränke, also bleiben für Anja die Spalten 4, 6 und 7 von Reihe 6 übrig. Britta war genau eine Spalte links von Anja, aber Spalte 3 ist durch Carsten belegt und Spalte 5 durch Finn. Welcher Platz bleibt dann für Anja?",answer:"Anja steht in Reihe 6, Spalte 7. Spalte 1 und 2 sind für Emil und Dirk, in Spalte 3 und 5 stehen Schränke, und bei Spalte 4 oder 6 müsste Britta in Spalte 3 (Carsten) oder 5 (Finn) sein."},{personId:"B",after:["F","C","A"],nudge:"Schau dir Reihe 4 an. Welche Felder sind dort noch frei, und wer kann dort noch hin?",reasoning:"Britta war genau eine Spalte links von Anja, also ist Spalte 6 für Britta. In Reihe 4 stehen in Spalte 1 bis 4 Bücherregale, Spalte 5 ist durch Finn belegt und Spalte 7 durch Anja. In Reihe 4 bleibt also nur ein Feld übrig, und jede Reihe enthält genau eine Person. Wer muss dann dort sein?",answer:"Britta steht in Reihe 4, Spalte 6. Reihe 4 hat sonst nur Bücherregale und die Spalten von Finn und Anja, und Spalte 6 ist für Britta."},{personId:"E",after:["F","C","A","B"],nudge:"Emil befand sich im Weinkeller und in einer Spalte weiter links als Dirk. Welche Reihe und welche Spalte bleiben für ihn übrig?",reasoning:"Der Weinkeller umfasst Reihe 6 und 7, und Reihe 6 ist durch Anja belegt, also ist Emil in Reihe 7. Dirk befand sich in der linken Hälfte, und Spalte 3 ist durch Carsten belegt, also ist Dirk in Spalte 1 oder 2. Emil befand sich in einer Spalte weiter links als Dirk, also muss Emil in Spalte 1 sein. Welches Feld ist das?",answer:"Emil steht in Reihe 7, Spalte 1. Reihe 6 gehört Anja, und weiter links als Dirk (Spalte 1 oder 2, denn Spalte 3 gehört Carsten) bleibt für Emil nur Spalte 1."},{personId:"D",after:["F","C","A","B","E"],nudge:"Was sagt Dirks Karte? Vergleich sie mit dem Feld von Finn.",reasoning:"Dirk befand sich genau zwei Reihen unter Finn, also in Reihe 5. Er befand sich in der linken Hälfte, und dort ist Spalte 1 durch Emil und Spalte 3 durch Carsten belegt. Welches Feld bleibt in Reihe 5 übrig?",answer:"Dirk steht in Reihe 5, Spalte 2. Er befand sich genau zwei Reihen unter Finn, und in der linken Hälfte sind Spalte 1 (Emil) und Spalte 3 (Carsten) schon belegt."},{personId:"V",after:["F","C","A","B","E","D"],nudge:"Alle Verdächtigen stehen. Welche Reihe und welche Spalte sind noch ganz leer?",reasoning:"Jede Reihe und jede Spalte enthält genau eine Person. Reihe 2 und Spalte 4 sind die einzige Reihe und die einzige Spalte, in denen noch niemand ist. Auf dem Feld, wo sie sich kreuzen, steht ein Sofa, und darauf kann jemand sein. Dort muss Volker also liegen.",answer:"Volker liegt in Reihe 2, Spalte 4. Das ist die einzige Reihe und die einzige Spalte, die noch leer sind."}],pe="Volker befand sich im Arbeitszimmer. Die einzige verdächtige Person dort ist Finn, also ist Finn der Täter.",Se={verdict:"goed",model:"keurder (claude-opus-5-5)",date:"2026-10-20"},ge={source:le,model:ue,date:oe,steps:ce,murderer:pe,review:Se},Re="e42c954df5cd",be="vertaler + keurder (claude-opus-5-5)",me="2026-10-20",fe=[{personId:"A",after:[],nudge:"Leg zuerst die Reihen von Dirk und Gerhard fest und schau dir dann Bettina und Christina an. Welche Reihen bleiben für Alina und Fabian?",reasoning:"Dirk ist in Reihe 2 und Gerhard in Reihe 3, also muss Bettina (obere Hälfte) in Reihe 1 oder 4 sein. Christina befand sich in einer Reihe weiter oben als Bettina, also ist Bettina in Reihe 4 und Christina in Reihe 1. Reihe 1 bis 4 sind damit für Christina, Dirk, Gerhard und Bettina, also müssen Alina und Fabian in Reihe 5 bis 8 sein. Dort kann Alina direkt neben einem Tisch in Reihe 5, Spalte 7 oder 8 oder in Reihe 6, Spalte 7 sein (Reihe 7, Spalte 8 zählt nicht: Eine Wand trennt dieses Feld vom Tisch). Fabian befand sich irgendwo oberhalb von Alina: In welcher Reihe kann Alina also nicht sein?",answer:"Alina steht in Reihe 6, Spalte 7. Reihe 1 bis 4 sind für Christina, Dirk, Gerhard und Bettina; direkt neben einem Tisch kann sie in Reihe 5 oder 6 sein, und in Reihe 5 könnte Fabian nicht irgendwo oberhalb von ihr sein."},{personId:"C",after:["A"],nudge:"Christina ist in Reihe 1, wie sich bei Alina gezeigt hat. Finde zuerst heraus, in welchem Raum Bettina ist, und lies dann Eriks Karte.",reasoning:"Bettina ist in Reihe 4, und eine andere Person in ihrem Raum war eine Frau. Im Boudoir geht das nicht (Christina ist in Reihe 1, Alina in der Küche), also ist Bettina in der Küche, in Spalte 4 oder weiter rechts. Erik befand sich in einer Spalte weiter rechts als eine Frau: nicht als Christina, denn er befand sich irgendwo links von ihr, also weiter rechts als Bettina oder Alina. Damit ist Erik in Spalte 5 oder weiter rechts, und Christina noch weiter rechts. In Reihe 1, Spalte 6 steht ein Bücherregal, und Spalte 7 ist durch Alina belegt: Welche Spalte bleibt übrig?",answer:"Christina steht in Reihe 1, Spalte 8. Erik befand sich in einer Spalte weiter rechts als Bettina (Küche, Spalte 4 oder weiter) oder Alina, also in Spalte 5 oder weiter, und Christina noch weiter rechts; in Reihe 1, Spalte 6 steht ein Bücherregal, und Spalte 7 ist belegt."},{personId:"G",after:["A","C"],nudge:"Gerhard ist in Reihe 3, aber nicht im Wintergarten. Welche Felder in Reihe 3 bleiben dann übrig?",reasoning:"Gerhard befand sich in der 3. Reihe und war nicht im Wintergarten, also nicht in Spalte 1, 2 oder 3. In Reihe 3, Spalte 5 und 6 steht ein Tisch, und Spalte 7 und 8 sind durch Alina und Christina belegt. Welches Feld ist noch frei?",answer:"Gerhard steht in Reihe 3, Spalte 4. Spalte 1 bis 3 sind der Wintergarten, in Reihe 3, Spalte 5 und 6 steht ein Tisch, und Spalte 7 und 8 sind belegt."},{personId:"B",after:["A","C","G"],nudge:"Bettina ist in der Küche in Reihe 4. Schau, welche Spalten noch frei sind, und denk an Erik.",reasoning:"Bettina ist in der Küche in Reihe 4, wie sich vorhin gezeigt hat. Spalte 4 und 8 sind durch Gerhard und Christina belegt, und in Reihe 4, Spalte 7 steht ein Tisch, also ist Bettina in Spalte 5 oder 6. Erik war in Spalte 5 oder weiter (siehe Christina) und irgendwo links von Christina in Spalte 8; Spalte 7 ist belegt, also ist Erik in Spalte 5 oder 6. Wäre Bettina in Spalte 6, müsste Erik in Spalte 5 sein, aber dann gäbe es keine Frau in einer Spalte weiter links als er. Welche Spalte bekommt Bettina dann?",answer:"Bettina steht in Reihe 4, Spalte 5. Sie muss in der Küche in Spalte 5 oder 6 sein, und bei Spalte 6 käme Erik in Spalte 5, ohne eine Frau weiter links als er."},{personId:"E",after:["A","C","G","B"],nudge:"Erik musste in Spalte 5 oder 6 sein. Bettina steht jetzt in Spalte 5. Welche Reihen sind in Spalte 6 noch frei?",reasoning:"Erik ist in Spalte 5 oder 6, wie sich vorhin gezeigt hat, und Spalte 5 ist durch Bettina belegt. Reihe 1, 3, 4 und 6 sind schon durch Christina, Gerhard, Bettina und Alina belegt, und Reihe 2 ist für Dirk. Fabian musste in Reihe 5 bis 8 und irgendwo oberhalb von Alina (Reihe 6) sein, also ist Reihe 5 für Fabian. In Reihe 8, Spalte 6 steht ein Schrank. Welches Feld in Spalte 6 bleibt für Erik?",answer:"Erik steht in Reihe 7, Spalte 6. Er muss in Spalte 6 sein; Reihe 1, 3, 4 und 6 sind belegt, Reihe 2 ist für Dirk, Reihe 5 für Fabian (irgendwo oberhalb von Alina), und in Reihe 8, Spalte 6 steht ein Schrank."},{personId:"F",after:["A","C","G","B","E"],nudge:"Fabian ist in Reihe 5. Lies den zweiten Satz auf seiner Karte.",reasoning:"Fabian ist in Reihe 5, wie sich vorhin gezeigt hat. Spalte 4 bis 8 sind belegt, also sind noch Spalte 1, 2 und 3 frei. Er war genau zwei Spalten rechts von einem Mann. In Spalte 1 oder 2 gibt es keine Spalte, die genau zwei Spalten links von ihm liegt. Welche Spalte bleibt übrig?",answer:"Fabian steht in Reihe 5, Spalte 3. Spalte 4 bis 8 sind belegt, und in Spalte 1 oder 2 kann kein Mann genau zwei Spalten links von ihm sein."},{personId:"V",after:["A","C","G","B","E","F"],nudge:"Wo liegt Veit? Schau, welche Reihen und Spalten noch frei sind, und denk an Dirks Karte.",reasoning:"Frei sind noch Reihe 2 und 8 sowie Spalte 1 und 2. Dirk befand sich in der 2. Reihe, also kommt Veit in Reihe 8. In Reihe 8, Spalte 1 steht eine Pflanze. Auf welchem Feld liegt Veit dann?",answer:"Veit liegt in Reihe 8, Spalte 2. Reihe 2 ist für Dirk, und in Reihe 8, Spalte 1 steht eine Pflanze."},{personId:"D",after:["A","C","G","B","E","F","V"],nudge:"Was sagt Dirks Karte?",reasoning:"Dirk befand sich in der 2. Reihe. Welche Spalte ist dort noch frei?",answer:"Dirk steht in Reihe 2, Spalte 1. Reihe 2 gehört ihm, und Spalte 1 ist die einzige freie Spalte."}],we="Veit liegt im Boudoir, und Fabian ist die einzige verdächtige Person in diesem Raum: Dirk ist im Wintergarten, Christina und Gerhard im Schlafzimmer, Bettina und Alina in der Küche und Erik im Gästezimmer. Fabian ist also der Täter.",ke={verdict:"goed",model:"keurder (claude-opus-5-5)",date:"2026-10-20"},ze={source:Re,model:be,date:me,steps:fe,murderer:we,review:ke},Be="fd37cde9aa3a",Fe="vertaler + keurder (claude-opus-5-5)",Ae="2026-10-20",De=[{personId:"B",after:[],nudge:"Schau dir Spalte 1 und 2 an: In welchen Räumen liegen sie, und wer kann laut der eigenen Karte dort überhaupt nicht sein?",reasoning:"Spalte 1 und 2 liegen im Boudoir und im Schlafzimmer, und in beiden steht ein Stuhl. Florian und Dennis waren in einem Raum ohne Stuhl, also nicht dort; Dennis war im selben Raum wie Carina, also Carina auch nicht. Anna befand sich irgendwo rechts von Carina und Elena genau vier Spalten rechts von ihr, also die beiden auch nicht. Spalte 1 und 2 sind also für Bernd und Veronika. Bernd befand sich in der 5. Reihe und neben keinem Sofa: In Reihe 5, Spalte 2 wäre er neben dem Sofa in Reihe 4 und 5, Spalte 1. Wer auf dem Sofa selbst ist, ist nicht daneben. Wo ist Bernd dann?",answer:"Bernd steht in Reihe 5, Spalte 1. Spalte 1 und 2 sind nur für Bernd und Veronika (beide Räume haben einen Stuhl), und in Reihe 5, Spalte 2 wäre Bernd neben einem Sofa."},{personId:"V",after:["B"],nudge:"Schau dir Reihe 7 an: Dort muss jemand sein. Überleg zuerst, in welcher Spalte Carina sein kann.",reasoning:"In Reihe 7 steht in Spalte 5, 6 und 7 ein Tisch, und Spalte 1 ist belegt. Elena befand sich genau vier Spalten rechts von Carina, also ist Carina in Spalte 1, 2 oder 3, und in einem Raum ohne Stuhl (dem von Dennis): Das geht nur in der Küche, in Spalte 3. Dennis ist auch in der Küche, und weil Spalte 3 für Carina ist, ist Spalte 4 für Dennis. Reihe 7, Spalte 3 und 4 fallen also weg. Spalte 2 ist für Veronika, wie sich vorhin gezeigt hat. Welches Feld bleibt in Reihe 7 übrig?",answer:"Veronika liegt in Reihe 7, Spalte 2. In Reihe 7 muss jemand sein: Spalte 1 ist belegt, in Spalte 5 bis 7 steht ein Tisch, und Spalte 3 und 4 sind für Carina und Dennis in der Küche."},{personId:"E",after:["B","V"],nudge:"Carina ist in Spalte 3. Wo ist Elena dann, und welcher Mann kann genau vier Reihen unter ihr sein?",reasoning:"Carina ist in Spalte 3, also ist Elena genau vier Spalten weiter in Spalte 7. Elena war genau vier Reihen über einem Mann, also ist sie in Reihe 1, 2 oder 3. In Reihe 7 ist Veronika, eine Frau, also fällt Reihe 3 weg. In Reihe 6 kann kein Mann sein: Dennis ist in der Küche, in Florians Raum gab es keinen Stuhl, und im Schlafzimmer steht ein Stuhl. Reihe 2 fällt also auch weg. Welcher Mann ist in Reihe 5?",answer:"Elena steht in Reihe 1, Spalte 7. Sie muss in Spalte 7 sein (genau vier Spalten rechts von Carina) und genau vier Reihen über einem Mann: Das ist Bernd in Reihe 5; Reihe 6 kann keinen Mann haben, und in Reihe 7 ist Veronika."},{personId:"A",after:["B","V","E"],nudge:"Schau dir Spalte 6 an: Welche Felder sind dort noch frei, und wer darf in diesem Raum sein?",reasoning:"In Spalte 6 muss jemand sein. Dort steht in Reihe 2 und 3 ein Klavier, in Reihe 4 ein Schrank und in Reihe 7 ein Tisch; Reihe 1 und 5 sind belegt. Nur Reihe 6, Spalte 6 bleibt übrig, im Schlafzimmer, wo ein Stuhl steht. Carina und Dennis sind in der Küche, und in Florians Raum gab es keinen Stuhl. Wer bleibt dann für dieses Feld übrig?",answer:"Anna steht in Reihe 6, Spalte 6. Das ist das einzige freie Feld in Spalte 6 (Klavier, Schrank und Tisch blockieren den Rest), und Carina, Dennis und Florian können nicht im Schlafzimmer mit seinem Stuhl sein."},{personId:"F",after:["B","V","E","A"],nudge:"Welche Spalte bleibt für Florian übrig? Schau dir danach Carinas Karte an: Genau drei Reihen unter ihr muss ein Mann sein.",reasoning:"Spalte 3 und 4 sind für Carina und Dennis, wie sich vorhin gezeigt hat, also kommt Florian in Spalte 5. Dort sind Reihe 1, 5 und 6 belegt, und in Reihe 7 steht ein Tisch, also Reihe 2, 3 oder 4. Carina befand sich genau drei Reihen über einem Mann; Reihe 1 ist belegt, und in Reihe 3 wäre Anna drei Reihen tiefer, also ist Carina in Reihe 2. Dennis ist dann in der Küche in Reihe 3. Welche Reihe bleibt für Florian?",answer:"Florian steht in Reihe 4, Spalte 5. Er muss in Spalte 5 sein; Reihe 2 ist für Carina (in Reihe 3 wäre Anna genau drei Reihen unter ihr) und Reihe 3 für Dennis in der Küche."},{personId:"C",after:["B","V","E","A","F"],nudge:"Carina ist in Spalte 3 der Küche. Wer ist genau drei Reihen unter jeder Reihe, die für sie noch frei ist?",reasoning:"Carina ist in der Küche in Spalte 3, also in Reihe 1, 2 oder 3. Reihe 1 ist belegt. Carina befand sich genau drei Reihen über einem Mann. Drei Reihen unter Reihe 3 ist Anna, eine Frau. Wer ist drei Reihen unter Reihe 2?",answer:"Carina steht in Reihe 2, Spalte 3. Reihe 1 ist belegt, und in Reihe 3 wäre Anna, eine Frau, drei Reihen tiefer; drei Reihen unter Reihe 2 ist Bernd."},{personId:"D",after:["B","V","E","A","F","C"],nudge:"Dennis ist der Letzte. Was sagt seine Karte, und welche Reihe und Spalte sind noch leer?",reasoning:"Dennis war im selben Raum wie Carina, also in der Küche. Alle anderen Personen haben schon ihren Platz, also bekommt er die einzige Reihe und die einzige Spalte, die noch frei sind. Liegt dieses Feld in der Küche?",answer:"Dennis steht in Reihe 3, Spalte 4: die einzige freie Reihe und Spalte, und dieses Feld liegt bei Carina in der Küche."}],Ce="Veronika liegt im Schlafzimmer, und Anna ist die einzige verdächtige Person in diesem Raum. Anna ist also die Täterin.",ve={verdict:"goed",model:"keurder (claude-opus-5-5)",date:"2026-10-20"},Ee={source:Be,model:Fe,date:Ae,steps:De,murderer:Ce,review:ve},We="c895d9aa52fd",Ie="vertaler + keurder (claude-opus-5-5)",Ve="2026-10-20",je=[{personId:"B",after:[],nudge:"Fang bei Bettina an: Welcher Mann kann genau drei Spalten links von ihr sein? Schau danach, wer Reihe 1, 2 und 8 füllen kann.",reasoning:"Günter ist in Spalte 1 (genau zwei Spalten links von Andreas in Spalte 3). Bettina befand sich genau drei Spalten rechts von einem Mann: Von Andreas aus wäre das Spalte 6 (die von Christian), von Christian aus Spalte 9 (gibt es nicht), also von Günter aus: Spalte 4. Wer kann Reihe 1, 2 oder 8 füllen? Diana nicht (Reihe 4). Andreas und Frieda nicht: Frieda war genau eine Reihe unter Andreas, in der unteren Hälfte; in Reihe 4, Spalte 3 steht ein Bücherregal, und Reihe 7, Spalte 3 liegt außerhalb, also ist Andreas in Reihe 5 oder 6 und Frieda in Reihe 6 oder 7. Christian nicht: In Spalte 6 liegen Reihe 1 und 2 außerhalb, und in Reihe 8 steht eine Pflanze. Günter nicht: In Reihe 1, Spalte 1 steht ein Schrank, Reihe 8 liegt außerhalb, und von Reihe 2 aus müsste in Reihe 4 ein Mann sein, der Reihe von Diana. Diese drei Reihen sind also für Bettina, Eva und Viktoria. Welche davon ist für Bettina in Spalte 4 eine Ecke?",answer:"Bettina steht in Reihe 1, Spalte 4: genau drei Spalten rechts von Günter. Nur sie, Eva und Viktoria können Reihe 1, 2 und 8 füllen; Reihe 2, Spalte 4 ist keine Ecke, und Reihe 8, Spalte 4 liegt außerhalb des Hauses."},{personId:"E",after:["B"],nudge:"Reihe 1, 2 und 8 sind für Bettina, Eva und Viktoria. Kann Eva in der untersten Reihe sein, wenn sie sich irgendwo oberhalb von einem Mann befand?",reasoning:"Wie sich bei Bettina gezeigt hat, sind Reihe 1, 2 und 8 für Bettina, Eva und Viktoria, und Bettina steht in Reihe 1. Eva befand sich irgendwo oberhalb von einem Mann, also nicht in Reihe 8: Sie kommt in Reihe 2. Spalte 1 ist für Günter, Spalte 3 für Andreas, Spalte 4 ist von Bettina besetzt, und Spalte 6 bis 8 liegen in Reihe 2 außerhalb des Hauses. Reihe 2, Spalte 5 liegt im Gästezimmer, genau wie Bettina, und Eva war nicht im selben Raum wie Bettina. Welches Feld bleibt in Reihe 2 übrig?",answer:"Eva steht in Reihe 2, Spalte 2. Sie musste in Reihe 2 (irgendwo oberhalb von einem Mann, also nicht in Reihe 8); Spalte 1 ist für Günter, Spalte 3 für Andreas, Spalte 4 ist besetzt, Spalte 5 liegt in Bettinas Raum, und Spalte 6 bis 8 liegen außerhalb des Hauses."},{personId:"D",after:["B","E"],nudge:"Diana war in der 4. Reihe und in einer Spalte weiter links als Christian. Welche Spalten sind in dieser Reihe noch frei?",reasoning:"Diana war in der 4. Reihe. Spalte 2 und 4 sind von Eva und Bettina besetzt, Spalte 1 ist für Günter und Spalte 6 für Christian. In Reihe 4, Spalte 3 steht ein Bücherregal und in Reihe 4, Spalte 8 eine Truhe. Reihe 4, Spalte 7 fällt weg, denn Diana befand sich in einer Spalte weiter links als Christian in Spalte 6. Was bleibt übrig?",answer:"Diana steht in Reihe 4, Spalte 5. Spalte 1, 2, 4 und 6 sind für andere, in Spalte 3 und 8 stehen ein Bücherregal und eine Truhe, und Spalte 7 liegt nicht weiter links als Christian."},{personId:"V",after:["B","E","D"],nudge:"Welche Reihe bleibt für Viktoria übrig? Schau dir danach Spalte 7 und 8 und Frieda an.",reasoning:"Reihe 1, 2 und 8 waren für Bettina, Eva und Viktoria, wie sich bei Bettina gezeigt hat, also kommt Viktoria in Reihe 8. Spalte 7 und 8 sind noch für Frieda und Viktoria, denn Günter, Andreas und Christian haben jeweils ihre eigene Spalte. Andreas kann in Spalte 3 nur in Reihe 5 oder 6 sein: In Reihe 4, Spalte 3 steht ein Bücherregal, Reihe 7 liegt außerhalb des Hauses, und Frieda musste genau eine Reihe tiefer in der unteren Hälfte sein. Frieda war also in Reihe 6 oder 7, und in Spalte 8 stehen dort Schränke. Spalte 7 ist also für Frieda. Welches Feld in Reihe 8 bleibt für Viktoria?",answer:"Viktoria liegt in Reihe 8, Spalte 8. Reihe 8 war für sie, Spalte 1 bis 4 liegen außerhalb des Hauses, Spalte 5 ist von Diana besetzt, in Reihe 8, Spalte 6 steht eine Pflanze, und Spalte 7 ist für Frieda."},{personId:"C",after:["B","E","D","V"],nudge:"Christian war in der 6. Spalte, und in seinem Raum war keine einzige Frau. In welchen Räumen von Spalte 6 steht schon eine Frau?",reasoning:"In Christians Raum war keine einzige Frau. In Spalte 6 liegen Reihe 1 und 2 außerhalb des Hauses, und in Reihe 8, Spalte 6 steht eine Pflanze. Reihe 3, Spalte 6 liegt im Gästezimmer, wo Bettina steht. In Spalte 6 gehören die Reihen 4 bis 6 zum Wintergarten, wo Diana steht. Welches Feld bleibt übrig?",answer:"Christian steht in Reihe 7, Spalte 6. Reihe 1 und 2 liegen außerhalb des Hauses, in Reihe 8 steht eine Pflanze, und im Gästezimmer steht Bettina, im Wintergarten Diana, beides Frauen."},{personId:"F",after:["B","E","D","V","C"],nudge:"Frieda gehört in Spalte 7, wie sich bei Viktoria gezeigt hat. Welche Reihen sind dort in der unteren Hälfte noch frei?",reasoning:"Spalte 7 ist für Frieda, wie sich bei Viktoria gezeigt hat. Frei sind noch Reihe 3, 5 und 6; Frieda befand sich in der unteren Hälfte, also in Reihe 5 oder 6. In Reihe 5 wäre Andreas genau eine Reihe höher, in Reihe 4, aber diese Reihe gehört Diana. Wohin kommt Frieda?",answer:"Frieda steht in Reihe 6, Spalte 7. In Spalte 7 sind nur Reihe 3, 5 und 6 frei; Reihe 3 liegt nicht in der unteren Hälfte, und in Reihe 5 müsste Andreas in Reihe 4, der Reihe von Diana."},{personId:"A",after:["B","E","D","V","C","F"],nudge:"Frieda steht jetzt auf dem Spielfeld. Was sagt ihre Karte über Andreas?",reasoning:"Frieda war genau eine Reihe unter Andreas, und Frieda steht in Reihe 6. Laut seiner eigenen Karte befand sich Andreas in der 3. Spalte. Wo landest du dann?",answer:"Andreas steht in Reihe 5, Spalte 3. Er war in Spalte 3 und genau eine Reihe über Frieda, die in Reihe 6 steht."},{personId:"G",after:["B","E","D","V","C","F","A"],nudge:"Günter ist der Letzte, der noch nicht auf dem Spielfeld steht. Was sagt seine Karte?",reasoning:"Reihe 3 und Spalte 1 sind die einzige Reihe und Spalte, die noch frei sind. Dort ist Günter genau zwei Spalten links von Andreas und genau zwei Reihen über ihm, genau wie seine Karte sagt.",answer:"Günter steht in Reihe 3, Spalte 1. Das ist die letzte freie Reihe und Spalte: genau zwei Spalten links von Andreas und genau zwei Reihen über ihm."}],$e="Viktoria liegt im Weinkeller. Frieda war die einzige verdächtige Person im Weinkeller; Christian ist im Schlafzimmer, Diana im Wintergarten, Andreas in der Küche, und Bettina, Eva und Günter sind im Gästezimmer und im Arbeitszimmer. Frieda ist also die Täterin.",Ke={verdict:"goed",model:"keurder (claude-opus-5-5)",date:"2026-10-20"},Ge={source:We,model:Ie,date:Ve,steps:je,murderer:$e,review:Ke},_e="e82e6e33b7b4",Te="vertaler + keurder (claude-opus-5-5)",Pe="2026-10-26",He=[{personId:"A",after:[],nudge:"Fang bei Antje an: Auf ihrer Karte steht die unterste Reihe. Welche Felder liegen dort innerhalb des Hauses?",reasoning:"Antje war in der untersten Reihe, also in Reihe 8. In Reihe 8 liegen die Spalten 1 bis 4 sowie die Spalten 7 und 8 außerhalb des Hauses. In Reihe 8, Spalte 6 steht eine Pflanze, dort kann niemand stehen. Welches Feld in Reihe 8 bleibt dann übrig?",answer:"Antje steht in Reihe 8, Spalte 5. In Reihe 8 liegen die Spalten 1 bis 4 sowie die Spalten 7 und 8 außerhalb des Hauses, und in Reihe 8, Spalte 6 steht eine Pflanze."},{personId:"V",after:["A"],nudge:"Antje ist im Boudoir, und laut ihrer Karte war dort noch eine Frau. Welche Frau kann das sein, und wo?",reasoning:"Laut Antjes Karte war eine andere Person in ihrem Raum eine Frau. Im Boudoir ist das Feld in Reihe 8, Spalte 5 durch Antje besetzt, und in Reihe 8, Spalte 6 steht eine Pflanze; nur das Feld in Reihe 7, Spalte 6 ist noch frei. Die Frauen sind Denise, Elena und Vesna. Denise war nicht im selben Raum wie Antje, und Elena war in der 2. Spalte. Wer muss dann auf dem freien Feld sein?",answer:"Vesna liegt in Reihe 7, Spalte 6. Es ist das einzige freie Feld im Boudoir, und Denise (nicht im selben Raum wie Antje) sowie Elena (2. Spalte) können dort nicht sein."},{personId:"G",after:["A","V"],nudge:"Schau auf Gregor: Er befand sich bei einem Fenster. Geh die Fenster durch und behalte Christoph, Elena und Florian im Blick.",reasoning:"Christoph war genau drei Reihen über Antje, also muss Christoph in Reihe 5 sein; Spalte 2 ist für Elena. Die Felder bei einem Fenster: Reihe 1, Spalte 1; Reihe 1, Spalte 2; Reihe 2, Spalte 8; Reihe 5, Spalte 8; Reihe 6, Spalte 1 (in Reihe 3, Spalte 8 steht eine Pflanze, Reihe 8, Spalte 5 ist durch Antje besetzt). Das Feld in Reihe 1, Spalte 2 (Elena) und das Feld in Reihe 5, Spalte 8 (Christoph) fallen weg. Gregor war genau eine Reihe über Florian, und Florian befand sich in einer Spalte weiter links als Antje, also muss er in Spalte 1 bis 4 sein. Wäre Gregor in Reihe 6, Spalte 1, wäre Florian in Reihe 7, aber dort steht Vesna. Wäre Gregor in Reihe 1, Spalte 1, wäre Florian in Reihe 2: In Reihe 2, Spalte 1 steht eine Pflanze, Spalte 2 ist für Elena, in Reihe 2, Spalte 3 steht der Schrank, und das Feld in Reihe 2, Spalte 4 liegt neben diesem Schrank (Florian befand sich neben keinem Schrank). Welches Fensterfeld bleibt übrig?",answer:"Gregor steht in Reihe 2, Spalte 8. Das Feld in Reihe 1, Spalte 1 fällt weg (in Reihe 2 passt Florian in keine Spalte weiter links als Antje: Pflanze, Elenas Spalte, Schrank, neben dem Schrank), ebenso Reihe 6, Spalte 1 (Reihe 7 ist durch Vesna besetzt), Reihe 1, Spalte 2 (Elena) und Reihe 5, Spalte 8 (Christoph)."},{personId:"C",after:["A","V","G"],nudge:"Christoph war genau drei Reihen über Antje. Welche Reihe ist das, und in welchen Spalten gibt es eine Pflanze?",reasoning:"Antje steht in Reihe 8, und Christoph war genau drei Reihen über Antje, also muss er in Reihe 5 sein. Pflanzen stehen in Spalte 1 (Reihe 2), Spalte 6 (Reihe 8) und Spalte 8 (Reihe 3). Spalte 6 ist durch Vesna besetzt und Spalte 8 durch Gregor. Welches Feld in Reihe 5 bleibt dann übrig?",answer:"Christoph steht in Reihe 5, Spalte 1. Er ist in Reihe 5 (genau drei Reihen über Antje), und von den Spalten mit einer Pflanze sind 6 (Vesna) und 8 (Gregor) schon besetzt."},{personId:"F",after:["A","V","G","C"],nudge:"Gregor war genau eine Reihe über Florian, und Florian befand sich in einer Spalte weiter links als Antje. Welche Reihe und welche Spalten sind das?",reasoning:"Gregor steht in Reihe 2, und er war genau eine Reihe über Florian, also muss Florian in Reihe 3 sein. Florian befand sich in einer Spalte weiter links als Antje, also in Spalte 1 bis 4. Spalte 1 ist durch Christoph besetzt, Spalte 2 ist für Elena, und in Reihe 3, Spalte 3 steht eine Truhe. Welches Feld bleibt übrig?",answer:"Florian steht in Reihe 3, Spalte 4. Er ist in Reihe 3 (gemäß Gregors Karte) und befand sich in einer Spalte weiter links als Antje; Spalte 1 (Christoph), Spalte 2 (Elena) und Spalte 3 (Truhe) fallen weg."},{personId:"E",after:["A","V","G","C","F"],nudge:"Elena war in der 2. Spalte, und in ihrem Raum war kein einziger Mann. Welche Reihen sind dort noch frei?",reasoning:"In Spalte 2 sind noch die Reihen 1, 4 und 6 frei. Das Feld in Reihe 4, Spalte 2 liegt im Schlafzimmer, in dem Florian (ein Mann) steht. Das Feld in Reihe 6, Spalte 2 liegt im Flur, in dem Christoph (ein Mann) steht. Welches Feld bleibt übrig?",answer:"Elena steht in Reihe 1, Spalte 2. Reihe 4 fällt weg (Florian im Schlafzimmer) und Reihe 6 ebenfalls (Christoph im Flur); im Speisezimmer ist kein Mann."},{personId:"B",after:["A","V","G","C","F","E"],nudge:"Björn war der einzige Mann im Raum. Schau, welche Reihen und Spalten noch frei sind.",reasoning:"Noch frei sind die Reihen 4 und 6 und die Spalten 3 und 7. Auf dem Feld in Reihe 4, Spalte 7 steht ein Tisch. Das Feld in Reihe 4, Spalte 3 liegt im Schlafzimmer, in dem Florian steht, und das Feld in Reihe 6, Spalte 3 im Flur, in dem Christoph steht; dort wäre Björn nicht der einzige Mann im Raum. Welches Feld bleibt übrig?",answer:"Björn steht in Reihe 6, Spalte 7. Auf dem Feld in Reihe 4, Spalte 7 steht ein Tisch, und auf dem Feld in Reihe 4, Spalte 3 (mit Florian im Raum) sowie auf dem Feld in Reihe 6, Spalte 3 (mit Christoph im Raum) wäre er nicht der einzige Mann im Raum."},{personId:"D",after:["A","V","G","C","F","E","B"],nudge:"Denise ist die Letzte, die noch nicht auf dem Spielfeld steht. Welche Reihe und welche Spalte sind noch frei?",reasoning:"Jede Reihe und jede Spalte enthält genau eine Person. Reihe 4 und Spalte 3 sind die letzten ohne Person, also muss Denise auf dem Feld sein, in dem sie sich kreuzen: in Reihe 4, Spalte 3. Dieses Feld liegt im Schlafzimmer, nicht im selben Raum wie Antje, das passt also zu Denises Karte.",answer:"Denise steht in Reihe 4, Spalte 3. Reihe 4 und Spalte 3 sind die letzten freien, und das Feld, in dem sie sich kreuzen, liegt im Schlafzimmer, nicht im selben Raum wie Antje."}],Me="Vesna liegt im Boudoir, und dort ist Antje die einzige verdächtige Person: Antje ist die Täterin. Christoph ist im Flur, Florian und Denise im Schlafzimmer, Elena im Speisezimmer, Gregor in der Bibliothek und Björn in der Küche.",Le={verdict:"goed",model:"keurder (claude-opus-5-5)",date:"2026-10-26"},xe={source:_e,model:Te,date:Pe,steps:He,murderer:Me,review:Le},Je=Object.assign({"/.demo/puzzles/i18n/de/L1-00037ru.json":s,"/.demo/puzzles/i18n/de/L1-00037sm.json":p,"/.demo/puzzles/i18n/de/L1-00037ss.json":w,"/.demo/puzzles/i18n/de/L2-000255s.json":C,"/.demo/puzzles/i18n/de/L2-000255v.json":$,"/.demo/puzzles/i18n/de/L2-000256n.json":M,"/.demo/puzzles/i18n/de/L3-0001qi0.json":Z,"/.demo/puzzles/i18n/de/L3-0002cvm.json":ne,"/.demo/puzzles/i18n/de/L3-0002cvz.json":he,"/.demo/puzzles/i18n/de/L4-0002klf.json":ge,"/.demo/puzzles/i18n/de/L4-0002klr.json":ze,"/.demo/puzzles/i18n/de/L4-0002km3.json":Ee,"/.demo/puzzles/i18n/de/L5-0002sbj.json":Ge,"/.demo/puzzles/i18n/de/L5-005oou4.json":xe});export{Je as default};
